      ],
      "assessment": {
        "nobel_worthiness": "A decisive prediction and experimental realization of a new topological state of matter, with lasting conceptual and materials impact.",
        "attribution": "Kane and Mele supplied the defining quantum-spin-Hall theory; Molenkamp led the landmark experimental confirmation.",
        "maturity": "The physics has been independently reproduced, broadly developed, and has reshaped quantum-materials research.",
        "uncertainties": [
          "The later quantum anomalous Hall developments create a difficult boundary between related prize formulations."
        ]
      }
    },
