      "proposed_laureates": [
        "Antoine Georges",
        "Gabriel Kotliar",
        "Dieter Vollhardt"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory made strongly correlated electrons quantitatively tractable and transformed the interpretation of real materials.",
        "attribution": "Georges, Kotliar and Vollhardt are the central architects of the modern method and its establishment.",
        "maturity": "It is a mature, extensively benchmarked framework integrated with electronic-structure calculations and experiment.",
        "uncertainties": [
          "As a methodological advance, its prize framing must distinguish fundamental discovery from a powerful theoretical tool."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B042",
      "proposed_laureates": [
        "Terunobu Miyazaki",
        "Jagadeesh S. Moodera",
        "Shinji Yuasa"
      ],
      "assessment": {
        "nobel_worthiness": "Large room-temperature tunnel magnetoresistance and coherent MgO junctions established a fundamental spin-transport effect with immense technological consequence.",
        "attribution": "Miyazaki and Moodera established large tunnel magnetoresistance, while Yuasa was pivotal for crystalline MgO junctions.",
        "maturity": "The effect is robust, quantitatively understood, and central to widely deployed magnetic-memory technologies.",
        "uncertainties": [
          "The appropriate division between the initial tunnel-magnetoresistance discovery and the later MgO breakthrough requires careful historical assessment."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B006",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "Sajeev John",
        "John D. Joannopoulos"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic band gaps supplied a powerful materials analogue of electronic band theory and opened an enduring field of light control.",
        "attribution": "John and Yablonovitch provided foundational concepts and demonstrations; Joannopoulos was central to the theoretical development.",
        "maturity": "Photonic crystals are thoroughly established experimentally and technologically, with broad influence across optics.",
        "uncertainties": [
          "Credit spans foundational theory, early experimental realization, and a large subsequent engineering community."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B031",
      "proposed_laureates": [
        "Bart J. van Wees",
        "David A. Wharam",
        "Michael Pepper"
      ],
      "assessment": {
        "nobel_worthiness": "The direct observation of quantized conductance made mesoscopic quantum transport experimentally concrete and profoundly influential.",
        "attribution": "The independent pioneering quantum-point-contact experiments of van Wees and the Wharam-Pepper collaboration support a compact attribution.",
        "maturity": "The phenomenon is exceptionally well confirmed and remains a standard platform for coherent nanoscale transport.",
        "uncertainties": [
          "Several closely timed experimental contributors may complicate a strictly limited attribution."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B021",
      "proposed_laureates": [
        "Steven T. Bramwell",
        "Roderich Moessner",
        "Shivaji L. Sondhi"
      ],
      "assessment": {
        "nobel_worthiness": "Spin ice revealed striking emergent gauge physics and effectively fractionalized magnetic monopoles in a tangible material system.",
        "attribution": "Moessner and Sondhi established the theoretical framework, while Bramwell led decisive experimental work on emergent monopoles.",
        "maturity": "Its signatures and theoretical interpretation have been extensively tested across frustrated magnetic materials.",
        "uncertainties": [
          "The monopoles are emergent excitations rather than elementary particles, demanding precise prize language."
        ]
      }
    },
    {
      "rank": 7,
